//! The tables the capture viewer reads: packet field layouts
//! (`packet-layouts.tsv`) and, optionally, the version chain
//! (`version-chain.tsv`).
//!
//! The built-in defaults are the repository's own tables: the layout file
//! compiled in and the version chain generated by `protocol::chain` (the
//! same rows as `documentation/version-chain.tsv`). A
//! `--tables DIR` replaces a built-in table with the file of the same name in
//! that folder; a file that is missing there keeps the built-in one. Nothing
//! is guessed: a malformed row is an error with its line number, and an id
//! or version that no row names simply has no layout.

use crate::difftest::trace::Dir;
use crate::protocol::ClientVersion;
use std::path::Path;

pub const LAYOUTS_FILE: &str = "packet-layouts.tsv";
pub const CHAIN_FILE: &str = "version-chain.tsv";

const BUILTIN_LAYOUTS: &str = include_str!("../../../../documentation/packet-layouts.tsv");

/// How one field is read from the payload.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Enc {
    /// One byte minus 0x20.
    Gchar,
    /// Two 7-bit groups, each byte minus 0x20.
    Gshort,
    Gint3,
    Gint4,
    Gint5,
    /// A GCHAR in half tiles, shown in tiles.
    Halftile,
    /// A GCHAR length, then that many bytes.
    Gstring,
    /// `Gstring` repeated to the end.
    GstringList,
    /// The rest of the payload as text.
    Text,
    /// The rest as comma text.
    Comma,
    /// A player prop stream (decoded by the trace decoder, not here).
    Props,
    /// The text of ids 24 and 32 (image records; decoded by the trace
    /// decoder, not here). Takes the rest of the payload.
    Showimg,
    /// The rest as bytes.
    Raw,
    /// No payload.
    None,
}

impl Enc {
    pub fn parse(s: &str) -> Option<Enc> {
        Some(match s {
            "gchar" => Enc::Gchar,
            "gshort" => Enc::Gshort,
            "gint3" => Enc::Gint3,
            "gint4" => Enc::Gint4,
            "gint5" => Enc::Gint5,
            "halftile" => Enc::Halftile,
            "gstring" => Enc::Gstring,
            "gstring_list" => Enc::GstringList,
            "text" => Enc::Text,
            "comma" => Enc::Comma,
            "props" => Enc::Props,
            "showimg" => Enc::Showimg,
            "raw" => Enc::Raw,
            "none" => Enc::None,
            _ => return Option::None,
        })
    }

    pub fn label(self) -> &'static str {
        match self {
            Enc::Gchar => "gchar",
            Enc::Gshort => "gshort",
            Enc::Gint3 => "gint3",
            Enc::Gint4 => "gint4",
            Enc::Gint5 => "gint5",
            Enc::Halftile => "halftile",
            Enc::Gstring => "gstring",
            Enc::GstringList => "gstring_list",
            Enc::Text => "text",
            Enc::Comma => "comma",
            Enc::Props => "props",
            Enc::Showimg => "showimg",
            Enc::Raw => "raw",
            Enc::None => "none",
        }
    }
}

/// How sure the table is about a field.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Known,
    /// The field exists and its bytes are known; what is inside is not
    /// decoded (or only partly understood).
    Partial,
    /// The field exists; its meaning is not known.
    Unknown,
}

impl Status {
    pub fn parse(s: &str) -> Option<Status> {
        match s {
            "known" => Some(Status::Known),
            "partial" => Some(Status::Partial),
            "unknown" => Some(Status::Unknown),
            _ => None,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Status::Known => "known",
            Status::Partial => "partial",
            Status::Unknown => "unknown",
        }
    }
}

/// One field of one packet, for the versions `from` to `to` (inclusive, in
/// chain order; `None` is open).
#[derive(Debug, Clone, PartialEq)]
pub struct LayoutRow {
    pub dir: Dir,
    pub id: u32,
    pub name: String,
    pub idx: u32,
    pub field: String,
    pub enc: Enc,
    pub from: Option<ClientVersion>,
    pub to: Option<ClientVersion>,
    pub status: Status,
    pub note: String,
}

/// Position of a version in chain order.
pub fn rank(v: ClientVersion) -> usize {
    ClientVersion::all_versions().iter().position(|&x| x == v).unwrap_or(usize::MAX)
}

impl LayoutRow {
    pub fn applies_to(&self, v: ClientVersion) -> bool {
        let r = rank(v);
        self.from.is_none_or(|f| rank(f) <= r) && self.to.is_none_or(|t| r <= rank(t))
    }
}

/// One row of `version-chain.tsv`.
#[derive(Debug, Clone, PartialEq)]
pub struct ChainRow {
    pub step: u32,
    pub label: String,
    pub kind: String,
    pub area: String,
    pub field: String,
    pub detail: String,
}

#[derive(Debug, Clone, Default)]
pub struct Tables {
    pub rows: Vec<LayoutRow>,
    /// The version chain rows (built in, or from `--tables`).
    pub chain: Vec<ChainRow>,
    /// Where each table came from, for `capture tables`.
    pub sources: Vec<(String, String)>,
}

impl Tables {
    /// The compiled-in defaults.
    pub fn builtin() -> Tables {
        let rows = parse_layouts(BUILTIN_LAYOUTS).expect("built-in packet-layouts.tsv is valid (a test checks it)");
        let chain = parse_chain(&crate::protocol::chain::render(crate::protocol::chain::Format::Tsv, None))
            .expect("the generated version chain is valid tsv (a test checks it)");
        Tables {
            rows,
            chain,
            sources: vec![(LAYOUTS_FILE.into(), "built-in".into()), (CHAIN_FILE.into(), "built-in (generated)".into())],
        }
    }

    /// Built-ins, with the files found in `dir` replacing or adding to them.
    pub fn load_dir(dir: &Path) -> Result<Tables, String> {
        if !dir.is_dir() {
            return Err(format!("--tables {}: not a folder", dir.display()));
        }
        let mut t = Tables::builtin();
        let lay = dir.join(LAYOUTS_FILE);
        if lay.is_file() {
            let text = std::fs::read_to_string(&lay).map_err(|e| format!("{}: {e}", lay.display()))?;
            t.rows = parse_layouts(&text).map_err(|e| format!("{}: {e}", lay.display()))?;
            t.sources[0].1 = lay.display().to_string();
        }
        let ch = dir.join(CHAIN_FILE);
        if ch.is_file() {
            let text = std::fs::read_to_string(&ch).map_err(|e| format!("{}: {e}", ch.display()))?;
            t.chain = parse_chain(&text).map_err(|e| format!("{}: {e}", ch.display()))?;
            t.sources[1].1 = ch.display().to_string();
        }
        Ok(t)
    }

    /// Rows of one packet that apply to `v` (or all rows of the packet when
    /// `v` is `None`), in field order.
    pub fn rows_for(&self, dir: Dir, id: u32, v: Option<ClientVersion>) -> Vec<&LayoutRow> {
        let mut r: Vec<&LayoutRow> =
            self.rows.iter().filter(|r| r.dir == dir && r.id == id && v.is_none_or(|v| r.applies_to(v))).collect();
        r.sort_by_key(|r| r.idx);
        r
    }

    /// The name a table row gives a packet.
    pub fn name_of(&self, dir: Dir, id: u32) -> Option<&str> {
        self.rows.iter().find(|r| r.dir == dir && r.id == id).map(|r| r.name.as_str())
    }

    /// Ids (with their direction) that have at least one row.
    pub fn ids(&self) -> Vec<(Dir, u32)> {
        let mut v: Vec<(Dir, u32)> = Vec::new();
        for r in &self.rows {
            if !v.contains(&(r.dir, r.id)) {
                v.push((r.dir, r.id));
            }
        }
        v.sort_by_key(|&(d, i)| (d as u8, i));
        v
    }
}

fn version_cell(s: &str, line: usize, what: &str) -> Result<Option<ClientVersion>, String> {
    if s == "-" {
        return Ok(None);
    }
    ClientVersion::from_label(s).map(Some).ok_or_else(|| format!("line {line}: unknown {what} version `{s}`"))
}

/// Parse `packet-layouts.tsv`. Lines starting with `#` and blank lines are
/// skipped; the header row is `dir id name idx field encoding from to status note`.
pub fn parse_layouts(text: &str) -> Result<Vec<LayoutRow>, String> {
    let mut rows = Vec::new();
    let mut seen_header = false;
    for (n, line) in text.lines().enumerate() {
        let n = n + 1;
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let c: Vec<&str> = line.split('\t').collect();
        if !seen_header {
            if c.len() < 9 || c[0] != "dir" || c[1] != "id" {
                return Err(format!("line {n}: expected the header row `dir id name idx field encoding from to status note`"));
            }
            seen_header = true;
            continue;
        }
        if c.len() < 9 {
            return Err(format!("line {n}: expected at least 9 columns, got {}", c.len()));
        }
        let bad = |what: &str, v: &str| format!("line {n}: bad {what} `{v}`");
        let from = version_cell(c[6], n, "from")?;
        let to = version_cell(c[7], n, "to")?;
        if let (Some(f), Some(t)) = (from, to) {
            if rank(f) > rank(t) {
                return Err(format!("line {n}: `from` {} is after `to` {}", c[6], c[7]));
            }
        }
        rows.push(LayoutRow {
            dir: Dir::parse(c[0]).ok_or_else(|| bad("direction", c[0]))?,
            id: c[1].parse().map_err(|_| bad("id", c[1]))?,
            name: c[2].to_string(),
            idx: c[3].parse().map_err(|_| bad("idx", c[3]))?,
            field: c[4].to_string(),
            enc: Enc::parse(c[5]).ok_or_else(|| bad("encoding", c[5]))?,
            from,
            to,
            status: Status::parse(c[8]).ok_or_else(|| bad("status", c[8]))?,
            note: c.get(9).copied().unwrap_or("").to_string(),
        });
    }
    if !seen_header {
        return Err("no header row".into());
    }
    Ok(rows)
}

/// Parse `version-chain.tsv` (`step label token basis kind area field detail`).
pub fn parse_chain(text: &str) -> Result<Vec<ChainRow>, String> {
    let mut rows = Vec::new();
    let mut seen_header = false;
    for (n, line) in text.lines().enumerate() {
        let n = n + 1;
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let c: Vec<&str> = line.split('\t').collect();
        if !seen_header {
            if c.len() < 8 || c[0] != "step" {
                return Err(format!("line {n}: expected the version-chain header row"));
            }
            seen_header = true;
            continue;
        }
        if c.len() < 8 {
            return Err(format!("line {n}: expected 8 columns, got {}", c.len()));
        }
        rows.push(ChainRow {
            step: c[0].parse().map_err(|_| format!("line {n}: bad step `{}`", c[0]))?,
            label: c[1].to_string(),
            kind: c[4].to_string(),
            area: c[5].to_string(),
            field: c[6].to_string(),
            detail: c[7].to_string(),
        });
    }
    if !seen_header {
        return Err("no header row".into());
    }
    Ok(rows)
}

/// One line describing a packet's layout, with the fields the table does not
/// settle marked: `?name:enc` is unknown, `~name:enc` is only partly decoded.
pub fn layout_line(rows: &[&LayoutRow]) -> String {
    rows.iter()
        .filter(|r| r.enc != Enc::None)
        .map(|r| {
            let mark = match r.status {
                Status::Known => "",
                Status::Partial => "~",
                Status::Unknown => "?",
            };
            format!("{mark}{}:{}", r.field, r.enc.label())
        })
        .collect::<Vec<_>>()
        .join(", ")
}

/// Problems in a table that are not parse errors: a row's name that
/// disagrees with the built-in packet names, two fields at one position for
/// the same version, a layout with fields after a field that takes the rest
/// of the payload.
pub fn lint(t: &Tables) -> Vec<String> {
    use crate::difftest::names::{pli_name, plo_name};
    let mut out = Vec::new();
    for (dir, id) in t.ids() {
        let builtin = match dir {
            Dir::C2S => pli_name(id),
            Dir::S2C => plo_name(id),
        };
        if let (Some(b), Some(n)) = (builtin, t.name_of(dir, id)) {
            if b != n {
                out.push(format!("{} {id}: table name {n} differs from the built-in name {b}", dir.label()));
            }
        }
        for &v in ClientVersion::all_versions() {
            let rows = t.rows_for(dir, id, Some(v));
            for w in rows.windows(2) {
                if w[0].idx == w[1].idx {
                    out.push(format!("{} {id} {}: fields {} and {} share position {}", dir.label(), v.label(), w[0].field, w[1].field, w[0].idx));
                    break;
                }
            }
            let takes_rest = |e: Enc| matches!(e, Enc::Text | Enc::Comma | Enc::Raw | Enc::GstringList | Enc::Props | Enc::Showimg);
            if let Some(i) = rows.iter().position(|r| takes_rest(r.enc)) {
                if i + 1 < rows.len() {
                    out.push(format!("{} {id} {}: field {} takes the rest of the payload but is not last", dir.label(), v.label(), rows[i].field));
                    break;
                }
            }
        }
    }
    out.dedup();
    out
}
